import{_ as t,o as s,c as n,ah as a}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Notes et évaluations","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/enseignant/notes-et-evaluations.md","filePath":"src/guide/enseignant/notes-et-evaluations.md"}'),o={name:"guide/enseignant/notes-et-evaluations.md"};function r(i,e,l,u,c,d){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="notes-et-evaluations" tabindex="-1">Notes et évaluations <a class="header-anchor" href="#notes-et-evaluations" aria-label="Permalink to &quot;Notes et évaluations&quot;">​</a></h1><p>Cette page couvre la création d&#39;une évaluation et la saisie des notes qui lui sont associées. Si votre établissement note certaines classes par compétences plutôt que par notes chiffrées (typiquement crèche/maternelle), la dernière section explique comment y saisir vos observations.</p><h2 id="creer-une-evaluation" tabindex="-1">Créer une évaluation <a class="header-anchor" href="#creer-une-evaluation" aria-label="Permalink to &quot;Créer une évaluation&quot;">​</a></h2><ol><li>Ouvrez <strong>Enseignement → Évaluations</strong> dans le menu.</li><li>Cliquez sur <strong>Nouvelle évaluation</strong>.</li><li>Dans la section <strong>Contexte</strong>, choisissez la <strong>Classe</strong>, la <strong>Matière</strong>, la <strong>Période scolaire</strong> et le <strong>Type d&#39;évaluation</strong> — les quatre listes ne proposent que vos propres affectations classe/matière.</li><li>Dans la section <strong>Détails</strong>, renseignez l&#39;<strong>Intitulé</strong> de l&#39;évaluation, sa <strong>Note maximale</strong> (20 par défaut, modifiable) et sa <strong>Date</strong>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><h2 id="retrouver-une-evaluation" tabindex="-1">Retrouver une évaluation <a class="header-anchor" href="#retrouver-une-evaluation" aria-label="Permalink to &quot;Retrouver une évaluation&quot;">​</a></h2><p>Sur la page <strong>Évaluations</strong>, utilisez le champ de recherche (par intitulé) et le filtre par classe pour retrouver une évaluation dans la liste, qui affiche pour chacune sa classe, sa matière, sa période et sa date. Cliquer sur une ligne ouvre un panneau de détail.</p><h2 id="saisir-les-notes" tabindex="-1">Saisir les notes <a class="header-anchor" href="#saisir-les-notes" aria-label="Permalink to &quot;Saisir les notes&quot;">​</a></h2><ol><li>Depuis la liste des évaluations, cliquez sur <strong>Notes</strong> sur la ligne de l&#39;évaluation concernée. En haut de la page, la pastille <strong>Noté sur…</strong> rappelle le barème, également affiché dans chaque champ de note.</li><li>Pour chaque élève, saisissez sa <strong>Note</strong> et, le cas échéant, un <strong>Bonus/malus</strong>. Vous pouvez écrire les décimales avec une virgule (« 12,5 »). La touche <strong>Entrée</strong> passe directement à la note de l&#39;élève suivant, comme dans un tableur.</li><li>Un clic suffit pour changer le <strong>Statut</strong> : <strong>Noté</strong>, <strong>Absent</strong> ou <strong>Dispensé</strong>. Un élève absent ou dispensé n&#39;a pas de note : ses champs se désactivent. La colonne <strong>Moyenne de matière actuelle</strong> indique la moyenne de chaque élève dans la matière avant enregistrement.</li><li>La barre du bas indique combien de notes sont saisies (par exemple « 24/30 notes saisies ») et signale les modifications non enregistrées. Cliquez sur <strong>Enregistrer</strong> : toutes les lignes sont enregistrées en une seule fois.</li></ol><p>Chaque élève <strong>Noté</strong> doit avoir une note. S&#39;il en manque, rien n&#39;est enregistré : la barre du bas indique le nombre de champs à corriger et la page vous amène au premier. Si vous quittez la page avant d&#39;enregistrer, ERA vous demande de confirmer pour ne pas perdre votre saisie.</p><h2 id="modifier-ou-supprimer-une-evaluation" tabindex="-1">Modifier ou supprimer une évaluation <a class="header-anchor" href="#modifier-ou-supprimer-une-evaluation" aria-label="Permalink to &quot;Modifier ou supprimer une évaluation&quot;">​</a></h2><p>Depuis la liste, utilisez <strong>Modifier</strong> pour changer le contexte ou les détails d&#39;une évaluation. <strong>Supprimer</strong> l&#39;efface définitivement ainsi que <strong>toutes les notes qui lui sont associées</strong> — une boîte de dialogue vous demande confirmation avant que l&#39;action, irréversible, ne soit exécutée.</p><h2 id="observations-de-competences" tabindex="-1">Observations de compétences <a class="header-anchor" href="#observations-de-competences" aria-label="Permalink to &quot;Observations de compétences&quot;">​</a></h2><p>Certains départements — typiquement crèche et maternelle — sont notés par compétences plutôt que par notes chiffrées : l&#39;enseignant y est affecté à toute la classe, sans matière distincte, et l&#39;administrateur y définit une liste de compétences à observer (menu admin <strong>Paramétrage scolaire → Compétences</strong>). Si l&#39;une de vos classes relève d&#39;un tel département, une page <strong>Observations de compétences</strong> est disponible pour elle.</p><ol><li>Ouvrez la page <strong>Observations de compétences</strong> de la classe concernée.</li><li>Choisissez la <strong>période scolaire</strong> dans le sélecteur en haut de page — la liste des élèves et compétences se recharge automatiquement.</li><li>Pour chaque élève et chaque compétence, choisissez un niveau : <strong>Non acquis</strong>, <strong>En cours d&#39;acquisition</strong> ou <strong>Acquis</strong>, et ajoutez éventuellement un commentaire. Chaque élève a sa fiche, avec une ligne par compétence.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Un niveau est obligatoire pour <strong>chaque</strong> compétence de <strong>chaque</strong> élève : s&#39;il en manque un, rien n&#39;est enregistré, un message l&#39;indique en haut de la liste et les niveaux à compléter sont encadrés en rouge.</p><p>Si le département de la classe n&#39;a encore aucune compétence définie, la page affiche « Ce département n&#39;a aucune compétence à observer » — il faut alors qu&#39;un administrateur en crée avant que vous puissiez saisir quoi que ce soit.</p>',16)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
